// Decide which sheet rows still need enriching.
const cfg = $('Config').first().json;
const s = $getWorkflowStaticData('global');

s.updated = 0;
s.failed = 0;
s.loggedSample = 0;
s.failedProfiles = [];
s.pageFailedProfiles = 0;

const rows = $input.all().map((i) => i.json);
const val = (row, name) => (row[name] === undefined || row[name] === null ? '' : String(row[name]).trim());

let noUrl = 0;
let noOib = 0;
let alreadyDone = 0;
const out = [];

for (const row of rows) {
  const profile_url = val(row, 'Profile URL');
  const oib = val(row, 'OIB');
  const name = val(row, 'Name');

  // Any profile field already present means this row has been enriched.
  const enriched = val(row, 'Owner/Director') || val(row, 'Email') || val(row, 'MBS') ||
                   val(row, 'Founding Date') || val(row, 'NKD Code');

  if (!profile_url) { noUrl++; continue; }
  if (!oib) { noOib++; continue; }
  if (cfg.only_missing === true && enriched) { alreadyDone++; continue; }

  out.push({ json: { name, oib, profile_url, row_number: row.row_number, page: 0 } });
}

console.log('=== EmBRACE enrich: RUN START ===');
console.log(`Tab: "${cfg.source_tab}"  |  rows read: ${rows.length}`);
console.log(`Already enriched (skipped): ${alreadyDone}  |  no Profile URL: ${noUrl}  |  no OIB: ${noOib}`);

let selected = out;
if (cfg.test_mode === true) {
  selected = out.slice(0, Number(cfg.test_limit) || 5);
  console.log(`test_mode is ON: enriching only the first ${selected.length} of ${out.length} rows.`);
} else {
  console.log(`To enrich: ${selected.length} rows (~${Math.round(selected.length * 6 / 60)} min at 3s+request each).`);
}

if (!selected.length) console.log('Nothing to do.');
return selected;

// Extend the company item (search-page fields) with the profile-page fields.
// No Merge node: this is one sequential item, so we just add keys to it.
//
// The profile call returns RAW HTML (no extract_rules) and we parse it here.
// That is deliberate: it depends on nothing except the page's own Croatian
// labels, and it lets you SEE the page in this node's input when a field is
// missing. Add any label wording you find to LABELS below.
const base = $('Loop Over Rows').first().json;
const raw = $input.first().json;
const s = $getWorkflowStaticData('global');

const LABELS = {
  owner_director: ['Vlasnik', 'Vlasnici', 'Direktor', 'Direktori', 'Odgovorna osoba', 'Član uprave', 'Uprava'],
  email: ['E-mail', 'E-pošta', 'Email', 'E-mail adresa', 'Mail'],
  founding_date: ['Datum osnivanja', 'Datum upisa', 'Osnovan', 'Osnovana', 'Godina osnivanja'],
  nkd_code: ['NKD 2007', 'NKD', 'Šifra djelatnosti', 'Pretežita djelatnost', 'Djelatnost'],
  mbs: ['MBS', 'Matični broj subjekta', 'Matični broj'],
};

const ALL_LABELS = new Set(Object.values(LABELS).flat().map((l) => l.toLowerCase()));

const fields = { owner_director: '', email: '', founding_date: '', nkd_code: '', mbs: '' };

const html = typeof raw?.data === 'string' ? raw.data : (typeof raw === 'string' ? raw : '');
const failed = !!(raw && raw.error !== undefined) || !html;
const reason = failed
  ? (raw && raw.error !== undefined
      ? (typeof raw.error === 'string' ? raw.error : JSON.stringify(raw.error).slice(0, 300))
      : 'ScrapingBee returned no HTML body')
  : '';

if (!failed) {
  const NAMED = {
    nbsp: ' ', amp: '&', lt: '<', gt: '>', quot: '"', apos: "'",
    scaron: 'š', Scaron: 'Š', ccaron: 'č', Ccaron: 'Č', cacute: 'ć', Cacute: 'Ć',
    zcaron: 'ž', Zcaron: 'Ž', dstrok: 'đ', Dstrok: 'Đ', eacute: 'é', ndash: '-', mdash: '-',
  };

  const decode = (t) => t
    .replace(/&([A-Za-z][A-Za-z0-9]*);/g, (m, name) => (name in NAMED ? NAMED[name] : m))
    .replace(/&#(\d+);/g, (_, d) => String.fromCharCode(Number(d)))
    .replace(/&#x([0-9a-f]+);/gi, (_, h) => String.fromCharCode(parseInt(h, 16)));

  // Every tag boundary becomes a line break, so <span>MBS</span><span>123</span>
  // turns into "MBS" / "123" on consecutive lines.
  const lines = decode(
    html
      .replace(/<script[\s\S]*?<\/script>/gi, ' ')
      .replace(/<style[\s\S]*?<\/style>/gi, ' ')
      .replace(/<!--[\s\S]*?-->/g, ' ')
      .replace(/<[^>]+>/g, '\n')
  )
    .split('\n')
    .map((l) => l.replace(/\s+/g, ' ').trim())
    .filter(Boolean);

  const esc = (v) => v.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

  const fromLabels = (labels) => {
    for (const label of labels) {
      const re = new RegExp('^' + esc(label) + '\\s*:?\\s*(.*)$', 'i');
      for (let i = 0; i < lines.length; i++) {
        const m = lines[i].match(re);
        if (!m) continue;
        const candidate = (m[1].trim() || lines[i + 1] || '').trim();
        if (candidate && candidate.length <= 300 && !ALL_LABELS.has(candidate.toLowerCase().replace(/:$/, ''))) {
          return candidate;
        }
      }
    }
    return '';
  };

  for (const key of Object.keys(fields)) fields[key] = fromLabels(LABELS[key]);

  // Email needs its own handling: the value next to the "E-mail" label is often
  // a link whose text is "Pošalji"/"Kontakt", not the address itself.
  const EMAIL_RE = /[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/;
  const mailto = html.match(/mailto:([^"'?>\s]+)/i);
  if (mailto) {
    fields.email = decode(mailto[1]).trim();
  } else if (!EMAIL_RE.test(fields.email)) {
    const inLabel = fields.email.match(EMAIL_RE);
    const anywhere = lines.join(' ').match(EMAIL_RE);
    fields.email = (inLabel && inLabel[0]) || (anywhere && anywhere[0]) || '';
  }

  // Diagnostics: dump a readable slice of the page for the first company of the
  // run, and again whenever a field comes back empty, so the real label wording
  // is visible in the execution log.
  const missing = Object.keys(fields).filter((k) => !fields[k]);
  if (!s.loggedSample || missing.length) {
    if (!s.loggedSample) s.loggedSample = 0;
    if (s.loggedSample < 3) {
      s.loggedSample++;
      console.log(`--- PROFILE PAGE TEXT SAMPLE (${base.name}) ---`);
      console.log(`missing fields: ${missing.length ? missing.join(', ') : 'none'}`);
      console.log(lines.slice(0, 150).join(' | '));
      console.log('--- end sample ---');
    }
  }
} else {
  s.failedProfiles.push({ name: base.name, oib: base.oib, url: base.profile_url, page: base.page, reason });
  s.pageFailedProfiles = (s.pageFailedProfiles || 0) + 1;
  console.log(`!! PROFILE FETCH FAILED for ${base.name} (OIB ${base.oib}): ${reason}`);
  console.log('   Writing the row with search-page data only; profile columns left blank.');
}

return [{ json: { ...base, ...fields, profile_failed: failed } }];

const c = $('Add Profile Fields').first().json;
const s = $getWorkflowStaticData('global');
const filled = ['owner_director', 'email', 'founding_date', 'nkd_code', 'mbs'].filter((k) => c[k]);

if (c.profile_failed) {
  s.failed = (s.failed || 0) + 1;
} else {
  s.updated = (s.updated || 0) + 1;
}
console.log(`Row ${c.row_number} ${c.name} (OIB ${c.oib}): filled ${filled.length}/5 -> ${filled.join(', ') || 'nothing'}`);
return $input.all();

const cfg = $('Config').first().json;
const s = $getWorkflowStaticData('global');

console.log('=== EmBRACE enrich: RUN COMPLETE ===');
console.log(`Tab: "${cfg.source_tab}"`);
console.log(`Rows updated: ${s.updated || 0}  |  profile fetches that failed: ${s.failed || 0}`);
if ((s.failedProfiles || []).length) {
  console.log('Failed profiles (rows left blank, safe to re-run):');
  console.log(JSON.stringify(s.failedProfiles, null, 2));
}
if (cfg.test_mode === true) console.log('test_mode was ON -- set it to false to enrich every remaining row.');

return [{ json: { tab: cfg.source_tab, rows_updated: s.updated || 0, fetch_failures: s.failed || 0, failed_profiles: s.failedProfiles || [] } }];
